-- Finance analytics wiki section (top-level sibling of "Data modeling").
-- Idempotent: pages upsert by slug; parent wiring and wikilinks are join-based and
-- safe to re-run. Cross-section wikilinks resolve only once the target pages exist,
-- so re-run all five domain seeds after the first pass to wire cross-links.
-- Mirrors what was seeded to the live DB via the Supabase MCP (2026-06).

insert into pages (title, slug, kind, content, visibility) values ('Finance analytics', 'finance-analytics', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finance analytics is the part of analytics engineering that the board actually reads. It's the SaaS metrics canon, the unit economics, and the revenue mechanics underneath them: how a signed contract becomes recognized revenue, cash in the bank, and a clean ARR number everyone agrees on."}]},{"type":"paragraph","content":[{"type":"text","text":"It sits next to "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" the same way the other domain sections do. Data modeling gives you grain, entities, and a semantic layer. Finance analytics is what you build on top when the questions are about money."}]},{"type":"paragraph","content":[{"type":"text","text":"Two halves, same shape as the rest of the wiki. The theory is the metric definitions and the revenue plumbing. The practice is modeling it in the warehouse so the number in the board deck matches the number in the BI tool matches the number in the GL."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Theory"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The metrics — ","marks":[{"type":"bold"}]},{"type":"text","text":"the canon (MRR, ARR, retention, unit economics, efficiency), defined precisely enough to model."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The plumbing — ","marks":[{"type":"bold"}]},{"type":"text","text":"revenue recognition, the bookings-billings-revenue-cash distinction, billing mechanics, payment processors, dunning."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Practice"}]},{"type":"paragraph","content":[{"type":"text","text":"The MRR waterfall in dbt, modeling billing data, one source of truth for ARR, reconciling with the GL, and the finance semantic layer."}]},{"type":"paragraph","content":[{"type":"text","text":"The hardest thing in finance analytics is not the math. It's that nobody agrees on the definitions, so the same metric quietly means three things. The fix is the same one taro is built on: define each metric once, model it for humans and machines, and make everything read from it."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The SaaS metrics canon"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Finance analytics practice"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Finance voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The SaaS metrics canon', 'saas-metrics-canon', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There's a standard set of numbers every SaaS business runs on, and the uncomfortable truth is that almost none of them have a single agreed definition. NRR computed per-cohort or per-period. CAC with or without onboarding cost. Rule of 40 on free cash flow margin or EBITDA. The SaaS Metrics Standards Board exists precisely because vendors, VCs, and CFOs compute them differently."}]},{"type":"paragraph","content":[{"type":"text","text":"So the first rule of the canon is not a formula, it's a discipline: write down which convention you use, next to the number. A metric without its definition is a rumor."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The map"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recurring revenue — ","marks":[{"type":"bold"}]},{"type":"text","text":"MRR and ARR. The base everything else is built on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retention — ","marks":[{"type":"bold"}]},{"type":"text","text":"gross and net revenue retention, logo versus revenue churn, cohort curves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unit economics — ","marks":[{"type":"bold"}]},{"type":"text","text":"CAC, LTV, payback. Is a customer worth more than it cost to get them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficiency — ","marks":[{"type":"bold"}]},{"type":"text","text":"Rule of 40, magic number, burn multiple. Is the growth worth the spend."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each of these is a counting problem before it's a finance problem. Get the "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" of the underlying subscription data right, and the metrics fall out. Get it wrong and every rollup lies in a way that looks authoritative."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"MRR and ARR"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('MRR and ARR', 'mrr-and-arr', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MRR is monthly recurring revenue: the normalized, predictable subscription revenue you earn each month. ARR is the annual version, either MRR times twelve or the sum of contracted annual values. They sound trivial and they are where most of the mistakes start."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What counts and what doesn't"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recurring only — ","marks":[{"type":"bold"}]},{"type":"text","text":"subscription charges count. One-time setup fees, professional services, and usage overages do not, unless the overage is contractually recurring."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Normalized — ","marks":[{"type":"bold"}]},{"type":"text","text":"an annual plan is divided by twelve so a yearly and a monthly customer are comparable in the same month."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Two ARRs, one acronym — ","marks":[{"type":"bold"}]},{"type":"text","text":"annual recurring revenue is contracted; annualized run rate is MRR times twelve extrapolated forward. Same letters, different meaning. Say which."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"MRR is a contractual construct, not a cash one. It comes from the state of active subscriptions in the billing system, not from what hit the bank account this month. That distinction is the whole reason "},{"type":"wikilink","attrs":{"title":"Bookings, billings, revenue, cash"}},{"type":"text","text":" is its own page."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The SaaS metrics canon"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"MRR movements and the waterfall"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Bookings, billings, revenue, cash"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('MRR movements and the waterfall', 'mrr-movements-and-the-waterfall', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A single MRR number tells you where you are. The movements tell you how you got there, and that's what you actually steer by. The canonical identity, the MRR bridge or waterfall:"}]},{"type":"paragraph","content":[{"type":"text","text":"Ending MRR = Starting MRR + New + Expansion + Reactivation − Contraction − Churn.","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The five movements"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New — ","marks":[{"type":"bold"}]},{"type":"text","text":"first-ever paid subscription from a previously non-paying customer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expansion — ","marks":[{"type":"bold"}]},{"type":"text","text":"a net increase on an existing customer: upgrade, added seats, an expiring discount."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Contraction — ","marks":[{"type":"bold"}]},{"type":"text","text":"a net decrease while at least one subscription stays active: downgrade, dropped seats, a new discount."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Churn — ","marks":[{"type":"bold"}]},{"type":"text","text":"the customer cancels their last active subscription. The full final amount, negative."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reactivation — ","marks":[{"type":"bold"}]},{"type":"text","text":"a previously churned customer comes back to paid."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The edge cases are where modelers get burned. A customer who cancels then buys a pricier plan is churn plus reactivation, not expansion, unless you deliberately link the subscriptions. An equal-price plan swap nets to zero. Proration timing decides which month a movement lands in. The discipline is to make the five buckets reconcile exactly to ending minus starting, and to assert that with a test. See "},{"type":"wikilink","attrs":{"title":"The MRR waterfall in dbt"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"MRR and ARR"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The MRR waterfall in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Revenue retention (GRR and NRR)"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Revenue retention (GRR and NRR)', 'revenue-retention-grr-nrr', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Retention is the truest signal a SaaS business works, because keeping revenue is cheaper than winning it. Two metrics, and the gap between them tells a story."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gross revenue retention — ","marks":[{"type":"bold"}]},{"type":"text","text":"(starting MRR − contraction − churn) ÷ starting MRR. Excludes expansion, so it caps at 100%. How leaky is the bucket."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Net revenue retention — ","marks":[{"type":"bold"}]},{"type":"text","text":"(starting MRR + expansion − contraction − churn) ÷ starting MRR, existing customers only. Can exceed 100%. Does the base grow on its own."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"NRR above 100% means your existing customers are worth more this year than last before you close a single new deal. It's the metric public-market investors fixate on. Best-in-class lands around 120% and up; the median private company sits closer to 105% (directional, varies by source and year)."}]},{"type":"paragraph","content":[{"type":"text","text":"The convention trap: the Standards Board recommends a cohort basis, comparing a fixed set of customers year over year, but plenty of teams report a simpler period-over-period version. They produce different numbers. Also separate logo from revenue retention. Losing ten tiny accounts and ten enterprise accounts is the same logo churn and wildly different revenue churn. See "},{"type":"wikilink","attrs":{"title":"Churn and retention"}},{"type":"text","text":" for the customer-experience view of the same problem."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"MRR movements and the waterfall"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn and retention"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The finance semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Unit economics (CAC, LTV, payback)', 'unit-economics-cac-ltv-payback', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unit economics asks one question: is a customer worth more than it cost to acquire them, and how fast do you find out. Three numbers, due to David Skok's SaaS Metrics 2.0."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CAC — ","marks":[{"type":"bold"}]},{"type":"text","text":"total sales and marketing spend ÷ new customers acquired in the period. Decide blended versus paid-only, and fully-loaded versus ad-spend-only, and say which."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CAC payback — ","marks":[{"type":"bold"}]},{"type":"text","text":"CAC ÷ (new MRR × gross margin). Months to earn the acquisition cost back. Skok's rule of thumb is under twelve months."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LTV — ","marks":[{"type":"bold"}]},{"type":"text","text":"(ARPA × gross margin) ÷ revenue churn. Breaks down when churn is near zero, and is unreliable for young companies because it assumes steady-state churn."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"LTV:CAC has a folk benchmark of 3:1 or better. Worth knowing that the 3:1 rule came from mature, steady-state public SaaS and gets misapplied to seed-stage companies constantly. For a cash-constrained business, a fast payback beats a high ratio: an 8:1 ratio with a 30-month payback is worse than 4:1 at 9 months, because the second one self-funds its next cohort."}]},{"type":"paragraph","content":[{"type":"text","text":"The honest version of all of these is segmented, by channel and cohort, which is a "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" decision. A blended CAC hides the channel that's quietly unprofitable. The acquisition side of this lives in "},{"type":"wikilink","attrs":{"title":"Unit economics of acquisition"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Efficiency metrics (Rule of 40, magic number, burn multiple)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Unit economics of acquisition"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Efficiency metrics (Rule of 40, magic number, burn multiple)', 'efficiency-metrics', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Growth is only good if you can afford it. The efficiency metrics put growth and cost on the same line so you can tell the difference between a great business and an expensive one."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rule of 40 — ","marks":[{"type":"bold"}]},{"type":"text","text":"revenue growth rate % + profit margin % should clear 40. Specify whether the margin is free cash flow or EBITDA, because they disagree. Popularized by Brad Feld."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Magic number — ","marks":[{"type":"bold"}]},{"type":"text","text":"net new ARR in a quarter ÷ prior-quarter sales and marketing spend. Below 0.75 is struggling; above 1.0 says pour fuel on it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Burn multiple — ","marks":[{"type":"bold"}]},{"type":"text","text":"net cash burned ÷ net new ARR. Coined by David Sacks. Under 1 is near self-funding; over 2 is inefficient. The acceptable ceiling tightened to about 1.5 after 2022."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"These move together. A company that passes the Rule of 40 almost always has an attractive burn multiple, because they measure the same efficiency from opposite ends. The reason they belong in analytics engineering and not just the CFO's spreadsheet is that they're only trustworthy if growth and margin are defined once and reconcile to the GL. Otherwise you're adding two fuzzy numbers and trusting the sum."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Unit economics (CAC, LTV, payback)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Reconciling the metrics layer with the GL"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The finance semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Revenue recognition and ASC 606', 'revenue-recognition-asc-606', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenue recognition is the rule that you record revenue as you deliver the service, not when the cash arrives. ASC 606 is the standard that governs it, and it's the reason finance numbers and billing numbers never quite line up."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The five steps"}]},{"type":"paragraph","content":[{"type":"text","text":"Identify the contract, identify the distinct performance obligations, set the transaction price, allocate the price across the obligations, and recognize revenue as each obligation is satisfied. For a SaaS subscription that means recognizing ratably over the term."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Deferred revenue"}]},{"type":"paragraph","content":[{"type":"text","text":"When a customer prepays a year, you've got the cash but not the right to call it revenue yet. The unearned part sits as a liability called deferred revenue, or a contract liability under 606, and releases month by month. The identity to model: opening deferred revenue + billings − recognized revenue = closing deferred revenue. A $12,000 annual prepay is $12,000 cash on day one and $1,000 of revenue a month for twelve months."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":" problem as much as a finance one: the same dollar belongs to different periods depending on the lens, and the model has to keep all of them straight."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Bookings, billings, revenue, cash"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Subscription and billing mechanics"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Bookings, billings, revenue, cash', 'bookings-billings-revenue-cash', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is the single most useful distinction in finance analytics, and the one that causes the most board-deck errors. Four different numbers for what feels like the same deal, each measured at a different moment."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings — ","marks":[{"type":"bold"}]},{"type":"text","text":"the total value of the contract signed, including future periods. Measured at signature."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Billings — ","marks":[{"type":"bold"}]},{"type":"text","text":"the amount invoiced. Measured when the invoice goes out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenue — ","marks":[{"type":"bold"}]},{"type":"text","text":"the amount recognized under ASC 606. Measured as the service is delivered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cash — ","marks":[{"type":"bold"}]},{"type":"text","text":"money actually received. Measured at payment."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A $120k annual deal signed January 1 and invoiced upfront is $120k bookings, $120k billings, $120k cash, and only $10k revenue in January. Conflate any two of these and the number is wrong in a way that survives review because everyone assumes someone else checked. Model them as four separate measures, never one, and label every chart with which one it shows."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Revenue recognition and ASC 606"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"MRR and ARR"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Reconciling the metrics layer with the GL"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Subscription and billing mechanics', 'subscription-and-billing-mechanics', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The billing system, Stripe Billing, Chargebee, Recurly, Zuora, Maxio, is where recurring revenue actually lives. It manages plans, proration, coupons, taxes, and entitlements, and it's the source of truth for MRR because MRR is computed from subscription state, not from charges."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The mechanics that bite analysts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Proration — ","marks":[{"type":"bold"}]},{"type":"text","text":"change a plan mid-cycle and the system credits unused time and charges the new rate pro-rata. In Stripe, negative prorations aren't auto-refunded and positive ones often roll to the next invoice, so timing is subtle."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Upgrades and downgrades — ","marks":[{"type":"bold"}]},{"type":"text","text":"upgrades usually charge immediately (expansion); downgrades often defer to the next cycle (contraction). Both are configurable, so confirm the behavior before you model the movement."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Usage and metered billing — ","marks":[{"type":"bold"}]},{"type":"text","text":"API calls, seats, compute accumulate and bill in arrears, often as a hybrid of base plus overage. The fast-growing category and the messy one for MRR."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Entitlements — ","marks":[{"type":"bold"}]},{"type":"text","text":"what a paying plan is allowed to access. The map from a purchased SKU to feature access, and where mobile in-app purchase tools like RevenueCat earn their keep."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Because the billing system is the source of truth, the catalog "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" for finance are its objects: customer, subscription, subscription item, invoice, charge. Get those grains right and the waterfall builds itself."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Payment processors and merchant of record"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Modeling billing data"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Payment processors and merchant of record', 'payment-processors-and-mor', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Underneath billing sits the money movement. A payment processor (Stripe, Adyen, Braintree, PayPal) routes a card charge through the networks to the customer's bank and settles funds to yours. The lifecycle is authorization, capture, settlement, and it emits the data you reconcile cash against."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The objects that matter for reconciliation"}]},{"type":"paragraph","content":[{"type":"text","text":"Stripe's model is the de-facto reference: charge, payment intent, balance transaction (every change to your balance with the fee breakdown), invoice, dispute, refund, payout. The balance transaction is the canonical record for tying gross to fees to net."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Merchant of record versus processor"}]},{"type":"paragraph","content":[{"type":"text","text":"This distinction has real tax consequences. With a plain processor you are the merchant of record, so you owe sales tax, VAT, and GST registration and remittance in every jurisdiction, plus chargeback and PCI liability. With a merchant of record (Paddle, Lemon Squeezy, FastSpring) the provider becomes the legal seller and handles global tax and compliance for a higher fee. Note Stripe acquired Lemon Squeezy, so that part of the landscape is in flux."}]},{"type":"paragraph","content":[{"type":"text","text":"For the warehouse, the processor is a second source that has to reconcile against the billing system and the GL. Net cash, after fees and refunds and disputes, rarely equals billed MRR, and the gap is a model, not a mystery. See "},{"type":"wikilink","attrs":{"title":"Reconciling the metrics layer with the GL"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Subscription and billing mechanics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Dunning and involuntary churn"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Reconciling the metrics layer with the GL"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Dunning and involuntary churn', 'dunning-and-involuntary-churn', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not all churn is a decision. Voluntary churn is a customer choosing to leave. Involuntary churn is a subscription lapsing on a failed payment: an expired card, insufficient funds, a fraud block. The customer never meant to go, which makes it the highest-ROI churn to fix, because recovering it costs nothing in acquisition."}]},{"type":"paragraph","content":[{"type":"text","text":"It's bigger than it looks. Involuntary churn can be a small share of customers but a large share of total churn, often cited around a third or more (directional, vendor data). For a business with thin margins on retention, that's the cheapest revenue you'll ever recover."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Dunning"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Smart retries — ","marks":[{"type":"bold"}]},{"type":"text","text":"re-attempt failed charges on a schedule timed by likelihood of success, rather than a fixed cadence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pre-dunning — ","marks":[{"type":"bold"}]},{"type":"text","text":"warn customers before a card expires, heading off the failure entirely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Card account updater — ","marks":[{"type":"bold"}]},{"type":"text","text":"a network service that refreshes reissued card numbers automatically, with no customer action."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For analytics, involuntary churn is a modeling decision: you have to separate it from voluntary churn in the waterfall, or your retention numbers blame the product for what was really a billing failure. It's a leading indicator worth its own metric, and it ties straight to "},{"type":"wikilink","attrs":{"title":"Churn and retention"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Subscription and billing mechanics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Revenue retention (GRR and NRR)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn and retention"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Finance voices and canon', 'finance-voices-and-canon', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SaaS finance has a real canon, mostly practitioner blogs, VC research, and a standards effort. Who to read and why."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The metric frameworks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"David Skok — ","marks":[{"type":"bold"}]},{"type":"text","text":"For Entrepreneurs and SaaS Metrics 2.0, the foundational LTV, CAC, churn, and payback framework. Origin of the 3:1 and sub-twelve-month rules of thumb."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ben Murray, The SaaS CFO — ","marks":[{"type":"bold"}]},{"type":"text","text":"the practitioner-CFO canon: the five-pillar metrics framework and board-ready templates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SaaS Metrics Standards Board — ","marks":[{"type":"bold"}]},{"type":"text","text":"the effort to standardize NRR, GRR, and ARR definitions. The reason to say which convention you use."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Benchmarks and VC research"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bessemer (BVP) — ","marks":[{"type":"bold"}]},{"type":"text","text":"State of the Cloud and the efficiency-metric benchmarks: CAC payback, NDR, gross margin, the efficiency score."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"KeyBanc Private SaaS Survey — ","marks":[{"type":"bold"}]},{"type":"text","text":"the authoritative private-company benchmark dataset, run annually with Sapphire Ventures."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ChartMogul — ","marks":[{"type":"bold"}]},{"type":"text","text":"the de-facto reference for MRR-movement definitions and the metrics library."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Efficiency thinking"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"David Sacks (Craft Ventures) — ","marks":[{"type":"bold"}]},{"type":"text","text":"coined the burn multiple."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Brad Feld — ","marks":[{"type":"bold"}]},{"type":"text","text":"popularized the Rule of 40."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A caution worth repeating: every benchmark here is year- and source-specific, and the definitions are genuinely non-standard. Cite the report, and state the convention.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Finance analytics practice', 'finance-analytics-practice', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The theory is the definitions. This hub is the build: turning billing and payment data into investor-grade metrics that reconcile, in the warehouse, with a paper trail."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The MRR waterfall as a tested dbt model."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Modeling billing data from Stripe and friends."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One authoritative ARR definition, and reconciling the metrics layer with the GL."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The finance semantic layer as the source of truth."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Finance analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The finance semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The MRR waterfall in dbt', 'the-mrr-waterfall-in-dbt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The MRR waterfall is the canonical SaaS finance model, and it's a satisfying one to build because it's pure "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" discipline. The shape:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stage the billing objects — ","marks":[{"type":"bold"}]},{"type":"text","text":"clean subscriptions, invoices, customers from the source."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Normalize to monthly value — ","marks":[{"type":"bold"}]},{"type":"text","text":"every active subscription item as a monthly amount, quantity times unit price, discounts applied."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Snapshot per customer per month — ","marks":[{"type":"bold"}]},{"type":"text","text":"a date spine crossed with customers, one row per customer per month with that month's MRR."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Classify the movement — ","marks":[{"type":"bold"}]},{"type":"text","text":"diff consecutive snapshots per customer. New versus reactivation needs a has-ever-paid flag; churn is prior positive and current zero; expansion versus contraction is the sign of the delta when both periods are positive."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Summarize — ","marks":[{"type":"bold"}]},{"type":"text","text":"one row per movement category per month for the dashboard."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The thing that makes it trustworthy is a test. Assert that New + Expansion + Reactivation − Contraction − Churn equals Ending minus Starting MRR, every month. If it doesn't reconcile, the model is lying, and the test catches it before the board does. This is "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" applied to the number that matters most."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"MRR movements and the waterfall"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Modeling billing data', 'modeling-billing-data', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Billing data gets into the warehouse two ways. A connector (the Fivetran Stripe connector plus the dbt_stripe package) lands raw objects and builds enriched models for you. Or Stripe's own Data Pipeline shares data directly into Snowflake, Redshift, or Databricks on a few-hour refresh, no ETL tool needed."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The tables to model"}]},{"type":"paragraph","content":[{"type":"text","text":"customer, subscription and subscription item, invoice and invoice line, charge or payment intent, balance transaction for fees and net, plus dispute, refund, credit note, coupon, payout, and the plan/price/product catalog. The Fivetran package's line-item-enhanced model denormalizes most of this into one analytics-ready table and even classifies the monthly movement for you."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Contracted versus billed"}]},{"type":"paragraph","content":[{"type":"text","text":"A subtlety the packages call out: contracted MRR (what the subscription says) and billed MRR (what got invoiced) differ, and you have to choose which one your metric means. Discounts apply at the subscription-item level. These are "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" decisions, and getting the grain right here is what makes the waterfall and every downstream metric honest."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Subscription and billing mechanics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The MRR waterfall in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('A single source of truth for ARR', 'single-source-of-truth-for-arr', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The recurring failure in finance analytics: ARR in the board deck, ARR in the BI tool, and ARR in the CRM are three different numbers, and the quarterly close turns into a reconciliation fire drill. The cause is always the same, the metric defined in more than one place."}]},{"type":"paragraph","content":[{"type":"text","text":"There are two ways out. Either one system holds the GAAP financials and the investor metrics on a single ledger, so there's nothing to reconcile, or a governed semantic layer in the warehouse defines ARR once and every surface queries it. Pick one, version the definition, and make it the only definition."}]},{"type":"paragraph","content":[{"type":"text","text":"This is exactly the "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" argument, applied to money. A metric defined once can't disagree with itself. The job of finance analytics engineering is to make that one definition the easiest one to use, so nobody is tempted to recompute it in a spreadsheet."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The finance semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Reconciling the metrics layer with the GL"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Reconciling the metrics layer with the GL', 'reconciling-metrics-with-gl', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There are three ledgers in a SaaS business and they never naturally agree: the billing system (contracted recurring revenue), cash (payouts net of fees, refunds, disputes), and the general ledger (recognized revenue under ASC 606, with the deferred-revenue schedule). Reconciling them is the work, and it should be a tested model, not a manual quarterly scramble."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The two reconciliations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Processor to GL — ","marks":[{"type":"bold"}]},{"type":"text","text":"tie balance-transaction net plus payouts to bank deposits, accounting for fees, refunds, chargebacks, and currency conversion as explicit lines."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Billing to product usage — ","marks":[{"type":"bold"}]},{"type":"text","text":"join subscription and entitlement data to product usage, so revenue connects to behavior. That's the basis for expansion and churn prediction."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Build the reconciliation as a recurring "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" check: metrics-layer ARR versus recognized revenue versus the GL, with a tolerance and an alert. When it drifts, you find out on a Tuesday, not in the audit. This is the finance version of the same rigor the rest of the platform runs on."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Bookings, billings, revenue, cash"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"A single source of truth for ARR"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The finance semantic layer', 'the-finance-semantic-layer', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything in this section points at one thing: define the finance metrics once, in code, and serve them to every surface. The semantic layer is where ARR, NRR, GRR, and the MRR-movement buckets stop being spreadsheet folklore and become governed definitions."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice that's a metrics layer (the dbt Semantic Layer with MetricFlow, or Cube) where the entities are customers and subscriptions, the measures are things like mrr and churned_mrr, and the metrics layer them into Net Revenue Retention with the active-contracts filter baked in. Then the board deck, the BI tool, the query editor, and any AI agent all return the same number, because they all read the same definition."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the technical implementation of single-source-of-truth, and it's the same thesis taro applies everywhere: meaning defined once, modeled for humans and machines, read by everything. Finance is just the domain where the cost of getting it wrong shows up fastest, in a board meeting."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"A single source of truth for ARR"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Efficiency metrics (Rule of 40, magic number, burn multiple)"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
